            <span style={{fontSize:9,fontFamily:"monospace",letterSpacing:"0.16em",color:dom.accent,background:"rgba(0,0,0,0.3)",padding:"3px 9px",borderRadius:2,textTransform:"uppercase"}}>{dom.label}</span>
