                  {a.refs.map((ref,i)=>(<a key={i} href={ref} target="_blank" rel="noopener noreferrer" style={{display:"block",fontSize:12,color:C.green,fontFamily:"monospace",textDecoration:"none",marginBottom:6,wordBreak:"break-all"}}>{ref}</a>))}
